// กรองเฉพาะผู้สนใจคะแนน ≥ 70 (HIGH INTENT) ที่ยังไม่ถูกยกระดับ — กันสร้างงานซ้ำ
const res = $input.first().json || {};
const leads = Array.isArray(res) ? res : (res.leads || res.data || res.items || []);
const HIGH = 70;
const out = [];
for (const l of leads) {
  const score = Number(l.engagementScore || l.score || 0) || 0;
  const already = l.escalated === true || l.hasOpenTask === true
    || String(l.stage || '').toUpperCase() === 'HIGH' || String(l.stage || '').toUpperCase() === 'HIGH_INTENT'
    || String(l.level || '').toUpperCase() === 'HIGH_INTENT' && l.hasOpenTask === true;
  if (score < HIGH || already) continue;
  const topics = (l.topics || l.interests || []).map(function (t) { return String((t && t.topic) || t); });
  out.push({ json: {
    prospectId: l.prospectId || l.id, name: l.name || null, phone: l.phone || null,
    email: l.email || null, channel: l.channel || 'LINE',
    score: score, level: l.level || 'HIGH', topics: topics,
    reason: 'คะแนนความสนใจ ' + score + ' (≥ ' + HIGH + ') — ต้องให้ตัวแทนมนุษย์ติดต่อ (AI ห้ามปิดการขายเอง)',
    at: new Date().toISOString()
  }, pairedItem: { item: 0 } });
}
if (out.length === 0) return [{ json: { none: true, reason: 'ไม่มีผู้สนใจคะแนน ≥ 70 ที่ยังไม่ถูกยกระดับ', checked: leads.length } }];
return out;

// สรุปผลการสร้างงานให้ตัวแทนจากผู้สนใจคะแนนสูง
const all = $('สร้างงานให้ตัวแทน (/api/agent-tasks)').all();
let okCount = 0, failCount = 0, firstError = null;
const taskIds = [];
for (const it of all) {
  const j = it.json || {};
  const c = j.statusCode === undefined ? null : Number(j.statusCode);
  const ok = j.ok === true || (c !== null && c >= 200 && c < 300);
  if (ok) { okCount++; if (j.taskId) taskIds.push(j.taskId); }
  else { failCount++; if (!firstError) firstError = String(j.error || j.message || ('HTTP ' + c)).slice(0, 300); }
}
return [{ json: {
  ok: failCount === 0, workflow: '06-lead-escalation', stage: 'escalate',
  detail: 'สร้างงานให้ตัวแทนสำเร็จ ' + okCount + ' งาน / ล้มเหลว ' + failCount + ' งาน' + (firstError ? ' — ' + firstError : ''),
  created: okCount, failed: failCount, taskIds: taskIds, firstError: firstError,
  alertText: (failCount === 0
    ? 'พบผู้สนใจความตั้งใจสูง (คะแนน ≥ 70) รายใหม่ ' + okCount + ' ราย — สร้างงานให้ตัวแทนแล้ว กรุณาติดต่อกลับโดยเร็ว'
    : 'แจ้งเตือน: สร้างงานให้ตัวแทนไม่สำเร็จ ' + failCount + ' งาน — ' + firstError),
  at: new Date().toISOString()
} }];
